204:     /// This method will try to merge the `VmMapping` with neighboring mappings
205:     /// that are adjacent and compatible, in order to reduce fragmentation.
206:     ///
207:     /// Make sure the insertion doesn't exceed address space limit.
208:     fn insert_try_merge(&mut self, vm_mapping: VmMapping) {
209:         self.total_vm += vm_mapping.map_size();
210:         let mut vm_mapping = vm_mapping;
211:         let addr = vm_mapping.map_to_addr();
