213:         if let Some(prev) = self.vm_mappings.find_prev(&addr) {
214:             let (new_mapping, to_remove) = vm_mapping.try_merge_with(prev);
215:             vm_mapping = new_mapping;
216:             if let Some(addr) = to_remove {
217:                 self.vm_mappings.remove(&addr);
218:             }
219:         }
