591:     /// Splits the mapping at the specified address.
592:     ///
593:     /// There are four conditions:
594:     /// 1. |-outside `range`-| + |------------within `range`------------|
595:     /// 2. |------------within `range`------------| + |-outside `range`-|
596:     /// 3. |-outside `range`-| + |-within `range`-| + |-outside `range`-|
597:     /// 4. |----------------------within `range` -----------------------|
598:     ///
599:     /// Returns (left outside, within, right outside) if successful.
600:     ///
601:     /// # Panics
602:     ///
603:     /// Panics if the mapping does not contain the range, or if the start or
604:     /// end of the range is not page-aligned.
605:     pub fn split_range(self, range: &Range<Vaddr>) -> (Option<Self>, Self, Option<Self>) {
606:         let mapping_range = self.range();
607:         if range.start <= mapping_range.start && mapping_range.end <= range.end {
608:             // Condition 4.
609:             (None, self, None)
610:         } else if mapping_range.start < range.start {
611:             let (left, within) = self.split(range.start).unwrap();
612:             if range.end < mapping_range.end {
613:                 // Condition 3.
614:                 let (within, right) = within.split(range.end).unwrap();
615:                 (Some(left), within, Some(right))
616:             } else {
617:                 // Condition 1.
618:                 (Some(left), within, None)
619:             }
620:         } else if mapping_range.contains(&range.end) {
621:             // Condition 2.
622:             let (within, right) = self.split(range.end).unwrap();
623:             (None, within, Some(right))
624:         } else {
625:             panic!("The mapping does not contain the splitting range");
626:         }
627:     }
