629:     /// Attempts to merge `self` with the given `vm_mapping` if they are
630:     /// adjacent and compatible.
631:     ///
632:     /// Two mappings are considered *adjacent* if the end address of `self`
633:     /// equals to the start address of `vm_mapping`, or vice versa.
634:     ///
635:     /// Two mappings are considered *compatible* if all of the following
636:     /// conditions are met:
637:     /// - They have the same access permissions.
638:     /// - They are both anonymous or share the same backing file.
639:     /// - Their file offsets are contiguous if file-backed.
640:     /// - Other attributes (e.g., shared/private flags, whether need to handle
641:     ///   page faults around, etc.) must also match.
642:     ///
643:     /// This method returns:
644:     /// - the merged mapping along with the address of the mapping
645:     ///   to be removed if successful.
646:     /// - the original `self` and a `None` otherwise.
647:     pub fn try_merge_with(self, vm_mapping: &VmMapping) -> (Self, Option<Vaddr>) {
648:         debug_assert!(!is_intersected(&self.range(), &vm_mapping.range()));
649: 
650:         let (left, right) = if self.map_to_addr < vm_mapping.map_to_addr {
651:             (&self, vm_mapping)
652:         } else {
653:             (vm_mapping, &self)
654:         };
655: 
656:         if let Some(merged) = try_merge(left, right) {
657:             (merged, Some(vm_mapping.map_to_addr))
658:         } else {
659:             (self, None)
660:         }
661:     }
662: }
