129: fn check_len(len: usize) -> Result<usize> {
130:     if len == 0 {
131:         return_errno_with_message!(Errno::EINVAL, "the mapping length is zero");
132:     }
133: 
134:     if len > VMAR_CAP_ADDR {
135:         return_errno_with_message!(Errno::ENOMEM, "the mapping length is too large");
136:     }
137: 
138:     Ok(len.align_up(PAGE_SIZE))
139: }
